const DEFAULT_STACK_LIMIT = 400;
const GEM_CURRENCY_STACK_LIMIT = 100000000000;
const { buildAtlasItemDefinition }: {
  buildAtlasItemDefinition(itemId: unknown, builders: {
    block(options?: ItemOptions): ItemDefinition;
    cleanItemId(value: unknown): string;
    displayNameForItemId(value: unknown): string;
  }): Readonly<ItemDefinition> | null;
} = require("./atlas_item_definition");

type ItemCategory = string;
type ItemOptions = Record<string, any>;
type ItemDefinition = Record<string, any> & {
  category: string;
  item_id?: string;
};
type ItemDefinitions = Record<string, ItemDefinition>;
type DropRule = Record<string, any>;
type AmountRange = ReadonlyArray<number>;
type FishingEntry = Record<string, any>;
type FishingTableSpec = Record<string, any>;
type StationRecipe = {
  id: string;
  output: Record<string, any>;
  cost: ReadonlyArray<Record<string, any>>;
};

function atlasImage(cell: ReadonlyArray<number>): Readonly<Record<string, any>> {
  return Object.freeze({
    atlas: "res://image.png",
    cell: Object.freeze(Array.from(cell)),
    cell_size: Object.freeze([32, 32]),
  });
}

