function applyTier1SpliceBalance(items: ItemDefinitions): void {
  for (const [blockId, balance] of Object.entries(TIER_1_SPLICE_BALANCE)) {
    const blockDefinition = items[blockId];
    if (!blockDefinition || blockDefinition.category !== "block") continue;

    const seedId = cleanItemId(blockDefinition.seed || `${blockId}_seed`);
    blockDefinition.seed = seedId;
    const balanceRecord = balance as Record<string, any>;
    blockDefinition.drop_rules = makeConfiguredSeedDropRules(
      blockId,
      seedId,
      balance.block_drop_chance,
      balance.seed_drop_chance,
      balanceRecord.break_gem_range || Object.freeze([]),
      balanceRecord.break_block_range || Object.freeze([]),
      balanceRecord.break_seed_range || Object.freeze([]),
    );
    blockDefinition.tree_drop_rules = makeConfiguredTreeDropRules(blockId, seedId, balance.tree_block_range, balance.tree_seed_range, balanceRecord.tree_gem_range || Object.freeze([]));

    if (!items[seedId]) {
      items[seedId] = seed(blockId, {
        display_name: `${String(blockDefinition.display_name || displayNameForItemId(blockId)).trim()} Seed`,
        rarity: blockDefinition.rarity || "common",
      });
    }

    if (items[seedId] && items[seedId].category === "seed") {
      items[seedId].grows_into = blockId;
      items[seedId].grow_time = balance.grow_time;
      items[seedId].max_grow_time = balance.grow_time;
      items[seedId].seed_box_icon = true;
    }
  }
}

function seededColourBlock(blockId: string, options: ItemOptions = {}): ItemDefinition {
  const seedId = cleanItemId(options.seed ?? `${blockId}_seed`);
  return colourBlock({
    ...options,
    seed: seedId,
    drop_rules: options.drop_rules || makeColouredBlockDropRules(blockId, seedId, 4),
    tree_drop_rules: options.tree_drop_rules || makeColouredBlockDropRules(blockId, seedId, 5),
  });
}

function prestigeColourBlock(options: ItemOptions = {}): ItemDefinition {
  return colourBlock({
    rarity: "epic",
    drop_rules: { seed_chance: 0, gem_range: [0, 0], drops_self: true },
    drops_self: true,
    ...options,
  });
}

function fishCatch(displayName: unknown, rarity: unknown, sellValue: unknown, options: ItemOptions = {}): ItemDefinition {
  return item("fish", {
    display_name: displayName,
    rarity,
    sell_value: sellValue,
    is_fish: true,
    quantity_type: "count",
    ...options,
  });
}

function fishingRod(displayName: unknown, rarity: unknown, options: ItemOptions = {}): ItemDefinition {
  return item("tool", {
    display_name: displayName,
    rarity,
    equipment_slot: "hand",
    equipable: true,
    fishing_rod: true,
    instance_tracked: true,
    ...options,
  });
}

